      "mainEntity": [
        {
          "@type": "Question",
          "name": "Can a family live on one income?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "By this test, in 2025 the median paycheck covers the local poverty threshold for two adults and two children and a $10,000 cushion in 238 of 521 areas. At the 25th percentile of pay, with no cushion at all, it covers the threshold in 103."
          }
        },
        {
          "@type": "Question",
          "name": "Which big cities are hardest to live in on one income?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Among metro areas with 1,000,000 or more jobs, the largest shortfalls with a $10,000 cushion are in Miami, Orlando, Riverside, Las Vegas and Los Angeles. The most room is in San Jose, Seattle and Washington, DC."
          }
        },
        {
          "@type": "Question",
          "name": "Is it getting harder to live on one income?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "From 2015 to 2025, the median wage fell as a percent of the local poverty threshold in 285 of the 290 areas we can compare, from 139% to 125% in the typical area."
          }
        },
        {
          "@type": "Question",
          "name": "Why does this differ from the official poverty rate?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "They measure different things. The official rate fell from 13.5% in 2015 to 10.2% in 2025, using a line that is the same everywhere and rises only with prices. This test sets one job's pay against a local threshold that follows what families spend on basics."
          }
        }
      ]
    }
